-- =====================================================================================
-- 91_catch_up_lab2.sql  ·  Wilderness Outfitters workshop
-- Lab 2 end state without Cortex Code: the same SQL as notebooks/lab2_christmas_stock_plan.ipynb,
-- then the finished Christmas planner app. Generated by _build/build.py; do not edit.
-- =====================================================================================
-- Point the session at the workshop
USE ROLE ACCOUNTADMIN;
USE WAREHOUSE WILDERNESS_WH;
USE DATABASE WILDERNESS_HOL;
USE SCHEMA LAB2_ANALYTICS;

CREATE OR REPLACE TABLE WILDERNESS_HOL.LAB2_ANALYTICS.TENT_RETURN_REASONS AS
SELECT FEEDBACK_ID, BATCH_CODE, FEEDBACK_DATE,
       AI_CLASSIFY(FEEDBACK_TEXT, ['POLE_FAULT', 'SEAM_FAULT', 'COULD_NOT_PITCH', 'CHANGE_OF_MIND', 'OTHER']):labels[0]::VARCHAR AS LABEL
FROM WILDERNESS_HOL.RAW.CUSTOMER_FEEDBACK
WHERE PRODUCT_ID = 'SKU-TNT-0102'
  AND FEEDBACK_SOURCE = 'RETURN_COMMENT'
  AND FEEDBACK_DATE >= '2026-07-01';

CREATE OR REPLACE DYNAMIC TABLE WILDERNESS_HOL.LAB2_ANALYTICS.CHRISTMAS_PLAN
  TARGET_LAG = '1 hour'
  WAREHOUSE = WILDERNESS_WH
  COMMENT = 'Christmas plan at 3 Nov 2026: one row per store, tents to send back and move'
AS
WITH tents AS (
  SELECT PRODUCT_ID FROM WILDERNESS_HOL.RAW.DIM_PRODUCT WHERE CATEGORY = 'Tents & Shelters'),
growth AS (
  SELECT s.STATE,
         SUM(IFF(f.ORDER_DATE BETWEEN '2026-11-01' AND '2026-11-03', f.QUANTITY, 0))
         / NULLIF(SUM(IFF(f.ORDER_DATE BETWEEN '2025-11-01' AND '2025-11-03', f.QUANTITY, 0)), 0) AS GROWTH
  FROM WILDERNESS_HOL.RAW.FCT_SALES_LINE f
  JOIN tents t ON t.PRODUCT_ID = f.PRODUCT_ID
  JOIN WILDERNESS_HOL.RAW.DIM_STORE s ON s.STORE_ID = f.STORE_ID
  WHERE f.ORDER_DATE BETWEEN '2025-11-01' AND '2025-11-03' OR f.ORDER_DATE BETWEEN '2026-11-01' AND '2026-11-03'
  GROUP BY 1),
last_year AS (
  SELECT f.STORE_ID, SUM(f.QUANTITY) AS TENTS_SOLD_LY
  FROM WILDERNESS_HOL.RAW.FCT_SALES_LINE f
  JOIN tents t ON t.PRODUCT_ID = f.PRODUCT_ID
  WHERE f.ORDER_DATE BETWEEN '2025-11-04' AND '2025-12-24'
  GROUP BY 1),
stock AS (
  SELECT i.STORE_ID, SUM(i.ON_HAND_UNITS) AS TENTS_ON_HAND,
         SUM(IFF(i.BATCH_CODE = 'B26-07', i.ON_HAND_UNITS, 0)) AS TENTS_TO_SEND_BACK
  FROM WILDERNESS_HOL.RAW.FCT_INVENTORY i
  JOIN tents t ON t.PRODUCT_ID = i.PRODUCT_ID
  GROUP BY 1),
plan AS (
  SELECT s.STORE_ID, s.STORE_NAME, s.STATE, s.LATITUDE, s.LONGITUDE,
         st.TENTS_ON_HAND, st.TENTS_TO_SEND_BACK,
         ROUND(ly.TENTS_SOLD_LY * g.GROWTH) AS FORECAST_TO_XMAS
  FROM WILDERNESS_HOL.RAW.DIM_STORE s
  JOIN stock st ON st.STORE_ID = s.STORE_ID
  JOIN last_year ly ON ly.STORE_ID = s.STORE_ID
  JOIN growth g ON g.STATE = s.STATE)
SELECT STORE_ID, STORE_NAME, STATE, LATITUDE, LONGITUDE, TENTS_ON_HAND, TENTS_TO_SEND_BACK, FORECAST_TO_XMAS,
       TENTS_ON_HAND - TENTS_TO_SEND_BACK - FORECAST_TO_XMAS AS GAP,
       IFF(TENTS_ON_HAND - TENTS_TO_SEND_BACK - FORECAST_TO_XMAS > 0, 'MOVE OUT', 'MOVE IN') AS ACTION
FROM plan;

CREATE OR REPLACE TABLE WILDERNESS_HOL.LAB2_ANALYTICS.SLEEPING_BAG_OFFER AS
WITH tent_orders AS (
  SELECT f.ORDER_ID, f.ORDER_DATE, f.MEMBER_ID, f.STORE_ID,
         MAX(IFF(p.CATEGORY = 'Tents & Shelters', p.PRODUCT_NAME, NULL)) AS TENT_NAME,
         MAX(IFF(p.KIT_GROUP = 'SLEEP', 1, 0)) AS HAS_SLEEP
  FROM WILDERNESS_HOL.RAW.FCT_SALES_LINE f
  JOIN WILDERNESS_HOL.RAW.DIM_PRODUCT p ON p.PRODUCT_ID = f.PRODUCT_ID
  WHERE f.ORDER_DATE BETWEEN '2026-11-01' AND '2026-11-03' AND f.MEMBER_ID IS NOT NULL
  GROUP BY 1, 2, 3, 4)
SELECT m.MEMBER_ID, m.FIRST_NAME, s.STORE_NAME, t.TENT_NAME, NULL::VARCHAR AS EMAIL
FROM tent_orders t
JOIN WILDERNESS_HOL.RAW.DIM_MEMBER m ON m.MEMBER_ID = t.MEMBER_ID
JOIN WILDERNESS_HOL.RAW.DIM_STORE s ON s.STORE_ID = t.STORE_ID
WHERE t.TENT_NAME IS NOT NULL AND t.HAS_SLEEP = 0
QUALIFY ROW_NUMBER() OVER (PARTITION BY m.MEMBER_ID ORDER BY t.ORDER_DATE, t.ORDER_ID) = 1;

UPDATE WILDERNESS_HOL.LAB2_ANALYTICS.SLEEPING_BAG_OFFER
SET EMAIL = AI_COMPLETE('claude-sonnet-4-6',
  'Write a short email from Wilderness Outfitters, an Australian outdoor retailer, to a Basecamp loyalty member. '
  || 'They are ' || FIRST_NAME || ', who bought a ' || TENT_NAME || ' at ' || STORE_NAME
  || ' this week but no sleeping bag or mat. Thank them for their tent, and offer 15% off a sleeping bag or mat '
  || 'before Christmas. Plain Australian English, under 80 words, no exclamation marks, no emoji. '
  || 'Return only a subject line and the body.')::VARCHAR
WHERE MEMBER_ID IN (SELECT MEMBER_ID FROM WILDERNESS_HOL.LAB2_ANALYTICS.SLEEPING_BAG_OFFER ORDER BY MEMBER_ID LIMIT 5);

CREATE OR REPLACE STREAMLIT WILDERNESS_HOL.LAB2_ANALYTICS.CHRISTMAS_PLANNER
  FROM '@WILDERNESS_HOL.SETUP.WORKSHOP_REPO/branches/main/apps/christmas_planner/'
  MAIN_FILE = 'streamlit_app.py'
  QUERY_WAREHOUSE = WILDERNESS_WH
  RUNTIME_NAME = 'SYSTEM$WAREHOUSE_RUNTIME'
  TITLE = 'Christmas planner'
  COMMENT = 'Christmas planner: reads WILDERNESS_HOL.LAB2_ANALYTICS.CHRISTMAS_PLAN';

ALTER STREAMLIT WILDERNESS_HOL.LAB2_ANALYTICS.CHRISTMAS_PLANNER ADD LIVE VERSION FROM LAST;

CALL WILDERNESS_HOL.SETUP.LOG_STEP('CATCH_UP_LAB2', 'OK',
  (SELECT COUNT(*) FROM WILDERNESS_HOL.LAB2_ANALYTICS.CHRISTMAS_PLAN));
